import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inverse of the Source-only sibling and the two presentation attachment ports. */
public final class SourceDollCommitDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",D=P+"NativeSourceDamageDisplay",N=P+"NativeSourceDollCommit";
 static void need(boolean b,String why){if(!b)throw new AssertionError(why);}
 static AbstractInsnNode prev(AbstractInsnNode n,int count){for(int i=0;i<count;i++)n=FreezeAcceptedMethods.prev(n);return n;}
 static MethodNode method(ClassNode c,String name,String desc){return c.methods.stream().filter(m->m.name.equals(name)&&(desc==null||m.desc.equals(desc))).findFirst().orElseThrow();}
 static InsnList remove(MethodNode m,AbstractInsnNode a,AbstractInsnNode b){var out=new InsnList();var stop=b.getNext();for(var n=a;n!=stop;){var next=n.getNext();m.instructions.remove(n);out.add(n);n=next;}return out;}
 static void same(ClassNode a,MethodNode before,ClassNode b,MethodNode after){need(Arrays.equals(FreezeSourceTargetDelta.body(a,before,before.name,before.access),FreezeSourceTargetDelta.body(b,after,before.name,before.access)),"original inverse "+a.name+'.'+before.name);}
 static void undoOrder(ClassNode old,ClassNode now,MethodNode before,MethodNode m){
  var commits=new ArrayList<MethodInsnNode>();for(var n:m.instructions)if(n instanceof MethodInsnNode c&&c.owner.equals(N)&&c.name.equals("commit"))commits.add(c);need(commits.size()==2,"two typed Source HP calls");
  var nodes=Arrays.asList(m.instructions.toArray());var calc=FreezeAcceptedMethods.call(m,PC,"nativeMagicDollTriggeredSkillDamage");var skill=commits.get(0);var bonus=commits.get(1);var visuals=new ArrayList<MethodInsnNode>();for(var n:m.instructions)if(n instanceof MethodInsnNode c&&c.owner.equals(PC)&&c.name.equals("publishNativeMagicDollProcVisual"))visuals.add(c);
  need(visuals.size()==2&&nodes.indexOf(visuals.get(0))<nodes.indexOf(calc)&&nodes.indexOf(calc)<nodes.indexOf(skill)&&nodes.indexOf(skill)<nodes.indexOf(visuals.get(1))&&nodes.indexOf(visuals.get(1))<nodes.indexOf(bonus),"Source damage-gfx, skill HP, skill visual, bonus HP order");
  for(var c:commits){c.owner=PC;c.name="commitNativeMagicDollProcDamage";need(c.desc.startsWith("(L"+PC+";"),"same original receiver");c.desc="("+c.desc.substring(("(L"+PC+";").length());c.setOpcode(INVOKEVIRTUAL);}
  var gate=FreezeAcceptedMethods.call(m,P+"CombatPlayerDamage","dollGate");var skillBranch=(JumpInsnNode)FreezeAcceptedMethods.next(gate);need(skillBranch.getOpcode()==IFLE,"same skill positive gate");var skillBlock=remove(m,prev(gate,3),skill);
  AbstractInsnNode bonusGuard=bonus;while(!(bonusGuard instanceof MethodInsnNode c&&c.owner.equals(P+"NativeMagicDollEffects$AttackProc")&&c.name.equals("additionalDamage")&&FreezeAcceptedMethods.next(c).getOpcode()==IFLE)){bonusGuard=bonusGuard.getPrevious();need(bonusGuard!=null,"original bonus positive gate");}
  var bonusBranch=(JumpInsnNode)FreezeAcceptedMethods.next(bonusGuard);var bonusBlock=remove(m,FreezeAcceptedMethods.prev(bonusGuard),bonus);
  var skills=FreezeAcceptedMethods.call(m,P+"NativeMagicDollEffects$AttackProc","skillTriggers");var skillStart=FreezeAcceptedMethods.prev(skills);var joinSkills=new LabelNode();bonusBranch.label=joinSkills;bonusBlock.add(joinSkills);m.instructions.insertBefore(skillStart,bonusBlock);
  var area=FreezeAcceptedMethods.call(m,P+"BattleSpellCatalog","areaAttackSpell");AbstractInsnNode jump=area;while(!(jump instanceof JumpInsnNode j&&j.getOpcode()==IFNULL))jump=FreezeAcceptedMethods.next(jump);var destination=((JumpInsnNode)jump).label;AbstractInsnNode iterate=destination;while(iterate.getOpcode()!=GOTO){iterate=iterate.getNext();need(iterate!=null,"original skill iteration");}var joinIteration=new LabelNode();skillBranch.label=joinIteration;skillBlock.add(joinIteration);m.instructions.insertBefore(iterate,skillBlock);
  same(old,before,now,m);
 }
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){
  var scope=Set.of(PC,D,D+"$Plan");var changed=new HashSet<String>();var originals=new HashSet<String>();for(var e:Collections.list(base.entries())){originals.add(e.getName());var following=jar.getJarEntry(e.getName());need(following!=null,"no deleted archive entries");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(following).readAllBytes()))changed.add(e.getName());}need(changed.equals(scope.stream().map(x->x+".class").collect(java.util.stream.Collectors.toSet())),"exact archive scope "+changed);
  int methods=0,accepted=0,valid=0;for(var name:scope){var old=FreezeSourceTargetDelta.read(base,name);var now=FreezeSourceTargetDelta.read(jar,name);need(now.fields.size()==old.fields.size()+(name.endsWith("$Plan")?1:0),"one optional visual proof field");for(int i=0;i<old.fields.size();i++){var x=old.fields.get(i);var y=now.fields.get(i);need(x.name.equals(y.name)&&x.access==y.access&&x.desc.equals(y.desc)&&Objects.equals(x.value,y.value),"old field unchanged");}if(name.endsWith("$Plan")){var f=now.fields.get(now.fields.size()-1);need(f.name.equals("nativeSourceDollProof")&&f.desc.equals("Ljava/lang/Object;")&&f.access==ACC_VOLATILE,"one volatile proof");}
   need(now.methods.size()==old.methods.size()+(name.equals(PC)?2:0),"bounded Source sibling and wrapper");
   for(var before:old.methods){boolean root=name.equals(PC)&&before.name.equals("applyNativeMagicDollAttackProcs");var after=method(now,root?"nativeSourceDollOriginalAttackProcs":before.name,before.desc);
    if(root){var wrapper=method(now,before.name,before.desc);need(FreezeAcceptedMethods.call(wrapper,N,"enabled").desc.equals("(L"+PC+";)Z"),"Source/BATTLE dispatch");need(FreezeAcceptedMethods.call(wrapper,PC,"nativeSourceDollOriginalAttackProcs")!=null&&FreezeAcceptedMethods.call(wrapper,PC,"nativeSourceDollOrderedAttackProcs")!=null,"unloaded/WORLD fallback remains original");undoOrder(old,now,before,method(now,"nativeSourceDollOrderedAttackProcs",before.desc));}
    for(var node:after.instructions.toArray())if(node instanceof MethodInsnNode c&&c.owner.equals(N)){if(c.name.equals("accepted")){need(name.equals(D)&&before.name.equals("acceptedState"),"same HP accepted-death boundary");after.instructions.remove(FreezeAcceptedMethods.prev(c));after.instructions.remove(c);accepted++;}else if(c.name.equals("valid")){need(name.equals(D+"$Plan")&&before.name.equals("valid"),"visual-only validity prefix");var ops=new ArrayList<AbstractInsnNode>();for(var n:after.instructions)if(n.getOpcode()>=0&&ops.size()<6)ops.add(n);need(ops.size()==6&&ops.get(2)==c&&ops.get(3).getOpcode()==IFNE&&ops.get(4).getOpcode()==ICONST_0&&ops.get(5).getOpcode()==IRETURN,"reject-only optional visual proof");for(var n:ops)after.instructions.remove(n);valid++;}else throw new AssertionError(c.name);}
    same(old,before,now,after);methods++;
   }
  }need(accepted==1&&valid==1,"exact two optional proof ports");int fresh=0;
  for(var e:Collections.list(jar.entries()))if(!originals.contains(e.getName())){need(Set.of(N+".class",N+"$NpcProof.class",N+"$PreVisual.class").contains(e.getName()),"only three bounded helper classes");fresh++;var c=FreezeSourceTargetDelta.read(jar,e.getName().replace(".class",""));for(var f:c.fields){need((f.access&ACC_STATIC)==0||f.value instanceof String,"no new global actor registry");need(!f.desc.contains("Context")&&!f.desc.contains("Receipt")&&!f.desc.contains("Scope"),"delayed proofs hold no action/receipt graph");}for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Executor"),"no new worker/TLS");if(n instanceof MethodInsnNode call)need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!call.owner.contains("Repository")&&!call.owner.contains("GameStateStore"),"no persistence authority");if(Set.of("valid","current","accepted").contains(m.name))need(n.getOpcode()!=MONITORENTER,"readonly final proof / accepted-state ports");}}
  need(fresh==3,"three helper classes");System.out.println("PASS independent doll inverse: "+methods+" original methods, Source-only ordering, original WORLD/unloaded body, bounded optional presentation proof and no workers/TLS/persistence");
 }}
}
